def curve(f):
    for i in range(len(PTS) - 1):
        x0, y0 = PTS[i]
        x1, y1 = PTS[i + 1]
        if f <= x1:
            return y0 + (y1 - y0) * (f - x0) / (x1 - x0)
    return -1.0

